# Audio fingerprinting: find spectral peaks, hash peak pairs, match against references.
def fingerprint(peaks):
    # peaks: list of (time, freq); hash pairs as (f1, f2, dt)
    h = set()
    pts = sorted(peaks)
    for i, (t1, f1) in enumerate(pts):
        for t2, f2 in pts[i+1:i+3+1]:
            h.add((f1, f2, round(t2 - t1, 2)))
    return h
refs = {name: fingerprint(px) for name, px in {'songA': [(0.0, 440), (0.1, 880), (0.2, 660)], 'songB': [(0.0, 220), (0.1, 330), (0.2, 440)]}.items()}
query = fingerprint([(0.0, 440), (0.1, 880), (0.2, 660), (0.3, 550)])
print("query hashes:", len(query))
for name, fp in refs.items():
    overlap = len(query & fp)
    score = overlap / max(len(query), 1)
    print(f"  {name}: {overlap} shared hashes (score {score:.2f})")

